    private static Sucursales getSucursal(List<Sucursales> sucursalesList, Integer idSucursal) {
        if (idSucursal == null || sucursalesList == null || sucursalesList.isEmpty()) {
            return null;
        }
        // Como sabemos que los IDs son secuenciales empezando desde 1, usamos index = id - 1
        return sucursalesList.get(idSucursal - 1);
    }

